const V_TX: Record<string, T> = { en, ro, fr, de, es, pt, hu, sv, it, bg, ar };
export function V(key: string, vars?: Record<string, string | number>): string {
  const l = textLang();
  let s = (V_TX[l] && V_TX[l][key]) || en[key] || key;
  if (vars) for (const [k, v] of Object.entries(vars)) s = s.split(`{${k}}`).join(String(v));
  return s;
}
export const V_LANGS = Object.keys(V_TX);
export const V_KEYS = Object.keys(en);
export function missingKeys(): Record<string, string[]> {
  const out: Record<string, string[]> = {};
  for (const l of V_LANGS) { const miss = V_KEYS.filter(k => !V_TX[l][k]); if (miss.length) out[l] = miss; }
  return out;
}
